def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    # Find the long, orthogonal L-shaped marker: one color forms a long
    # horizontal and vertical run meeting at a corner.
    markers = []
    for col in colors:
        cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == col}
        # connected components
        unseen = set(cells)
        while unseen:
            seed = unseen.pop(); q = [seed]; comp = {seed}
            for r, c in q:
                for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if p in unseen:
                        unseen.remove(p); comp.add(p); q.append(p)
            if len(comp) < 8:
                continue
            rs = [r for r,c in comp]; cs = [c for r,c in comp]
            # Candidate corner where at least 4 cells extend each way.
            for r,c in comp:
                vertical = sum((rr,c) in comp for rr in range(h))
                horizontal = sum((r,cc) in comp for cc in range(w))
                if vertical >= 4 and horizontal >= 4:
                    markers.append((col, comp, (r,c)))
    if not markers:
        return out
    marker_color, marker, corner = max(markers, key=lambda x: len(x[1]))
    # Collect non-background monochrome components, excluding the marker.
    comps = []
    seen = set()
    bg = max(colors, key=lambda v: sum(x == v for row in grid for x in row))
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col in (bg, marker_color) or (r,c) in seen:
                continue
            q = [(r,c)]; seen.add((r,c)); comp={(r,c)}
            for rr,cc in q:
                for p in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    pr,pc=p
                    if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == col and p not in seen:
                        seen.add(p); comp.add(p); q.append(p)
            r0=min(a for a,b in comp); c0=min(b for a,b in comp)
            shape=frozenset((a-r0,b-c0) for a,b in comp)
            comps.append((col, comp, shape, (sum(a for a,b in comp)/len(comp), sum(b for a,b in comp)/len(comp))))
    # Recolor the duplicate-shape object lying opposite the L's inside corner
    # (the L is a divider; the matching example on the far side is the target).
    for i, x in enumerate(comps):
        for y in comps[i+1:]:
            if x[2] != y[2]:
                continue
            # Estimate the marker's open quadrant from the arms.
            r,c=corner
            above = any(a < r and b == c for a,b in marker)
            below = any(a > r and b == c for a,b in marker)
            left = any(a == r and b < c for a,b in marker)
            right = any(a == r and b > c for a,b in marker)
            # Choose component across the corner from the direction of the arms.
            sx = 1 if above else (-1 if below else 0)
            sy = 1 if right else (-1 if left else 0)
            def side(z):
                dr=z[3][0]-r; dc=z[3][1]-c
                return (dr*sx + dc*sy)
            target = x if side(x) > side(y) else y
            for a,b in target[1]:
                out[a][b]=marker_color
            return out
    return out

