def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = [(r, c)]; seen.add((r, c)); cells = {(r, c)}
            for a, b in q:
                for x, y in ((a-1,b), (a+1,b), (a,b-1), (a,b+1)):
                    if 0 <= x < h and 0 <= y < w and grid[x][y] == color and (x,y) not in seen:
                        seen.add((x,y)); cells.add((x,y)); q.append((x,y))
            r0, c0 = min(x for x,y in cells), min(y for x,y in cells)
            shape = frozenset((x-r0,y-c0) for x,y in cells)
            comps.append((color, cells, shape))
    # The long L is the marker; locate its corner and orientation.
    marker = None
    for color, cells, shape in comps:
        for r, c in cells:
            vertical = [x for x in range(h) if (x,c) in cells]
            horizontal = [y for y in range(w) if (r,y) in cells]
            if len(vertical) >= 4 and len(horizontal) >= 4:
                marker = (color, cells, r, c, vertical, horizontal)
                break
        if marker:
            break
    if marker is None:
        return out
    mcolor, mcells, r, c, vertical, horizontal = marker
    vdir = -1 if min(vertical) < r else 1
    hdir = -1 if min(horizontal) < c else 1
    objs = [x for x in comps if x[0] != mcolor]
    # Find congruent objects. The copy on the open side of the L is the one
    # recolored to the marker's color.
    pairs = []
    for i, a in enumerate(objs):
        for b in objs[i+1:]:
            if a[2] == b[2]:
                pairs.append((a,b))
    if not pairs:
        return out
    def open_score(obj):
        cells = obj[1]
        cr = sum(x for x,y in cells) / len(cells)
        cc = sum(y for x,y in cells) / len(cells)
        return (cr-r)*(-vdir) + (cc-c)*(-hdir)
    a,b = max(pairs, key=lambda pair: max(open_score(pair[0]), open_score(pair[1])))
    target = a if open_score(a) > open_score(b) else b
    for x,y in target[1]:
