def _norm(cells):
    pts = list(cells)
    variants = []
    for flip in (1, -1):
        for k in range(4):
            p = []
            for r, c in pts:
                x, y = r, c * flip
                for _ in range(k):
                    x, y = y, -x
                p.append((x, y))
            mr, mc = min(x for x,y in p), min(y for x,y in p)
            variants.append(frozenset((x-mr,y-mc) for x,y in p))
    return min(variants, key=lambda s: sorted(s))

