def transform(grid):
    g = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    masks = [{c for c, v in enumerate(row) if v != bg} for row in grid]
    for r, row in enumerate(grid):
        # Fill a right-truncated row when another row has a similar pattern
        # and continues farther to the right.
        cols = masks[r]
        if not cols or row[-1] != bg:
            continue
        candidates = []
        for rr, ref in enumerate(masks):
            if rr == r or len(ref) <= len(cols):
                continue
            sim = len(ref & cols) / max(1, len(ref | cols))
            if sim >= 0.5 and max(ref) > max(cols):
                candidates.append((sim, len(ref), ref))
        if candidates:
            _, _, ref = max(candidates, key=lambda x: (x[0], x[1]))
            # Color the missing terminal run only if the reference supports it.
            last = max(cols)
            if all(c in ref for c in range(last + 1, len(row))):
                row_out = g[r]
                for c in range(last + 1, len(row)):
                    row_out[c] = 1
    return g

